namespace ghidra.app.plugin.core.decompile.actions;





using docking.action;
using ghidra.app.cmd.label;
using ghidra.app.decompiler;
using ghidra.app.decompiler;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.framework.cmd;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util;

public class RemoveLabelAction : AbstractDecompilerAction {

	private static readonly string[] POPUP_PATH = new string[] { "Remove Label" };
	private static readonly KeyStroke KEYBINDING = KeyStroke.getKeyStroke(KeyEvent.VK_DELETE, 0);

	public RemoveLabelAction() : base("Remove Label", KeyBindingType.SHARED)
    {

		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionRemoveLabel"));

		// same keybinding as the other remove actions
		setPopupMenuData(new MenuData(POPUP_PATH, "Decompile"));
		setKeyBindingData(new KeyBindingData(KEYBINDING));
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		ClangToken tokenAtCursor = context.getTokenAtCursor();
		if (!(tokenAtCursor is ClangLabelToken)) {
			return false;
		}

		Symbol symbol = getSymbol(context);
		return canRemoveSymbol(symbol);
	}

	private bool canRemoveSymbol(Symbol s) {
		return s != null && s.getSource() != SourceType.DEFAULT && !s.isExternal();
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		Symbol s = getSymbol(context);
		Command<Program> cmd =
			new DeleteLabelCmd(s.getAddress(), s.getName(), s.getParentNamespace());
		PluginTool tool = context.getTool();
		if (!tool.execute(cmd, context.getProgram())) {
			tool.setStatusInfo(cmd.getStatusMsg());
		}
	}
}
